export const IMAGE_MIME_TYPES = ["image/png", "image/jpeg"] as const;

export type ImageMimeType = (typeof IMAGE_MIME_TYPES)[number];

/** What the first bytes of a file say about it, whatever its name or declared type. */
export interface ImageSignature {
  mimeType: ImageMimeType;
  width: number;
  height: number;
}

const PNG_SIGNATURE = [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a];
const PNG_IHDR_TYPE = [0x49, 0x48, 0x44, 0x52];
const PNG_IHDR_DATA_LENGTH = 13;
const PNG_IHDR_END = 8 + 4 + 4 + 8; // signature, chunk length, chunk type, width and height

const JPEG_SIGNATURE = [0xff, 0xd8, 0xff];
const JPEG_MARKER_PREFIX = 0xff;
const JPEG_FILL_BYTE = 0xff;
const JPEG_START_OF_SCAN = 0xda;
const JPEG_END_OF_IMAGE = 0xd9;
const JPEG_MARKER_AND_LENGTH_SIZE = 4;
const JPEG_FRAME_HEADER_SIZE = 9; // marker, length, precision, height and width
// Start-of-frame markers are C0-CF, except C4 (Huffman tables), C8 (reserved) and CC (arithmetic tables).
const JPEG_NOT_A_FRAME = new Set([0xc4, 0xc8, 0xcc]);

function startsWith(bytes: Uint8Array, expected: readonly number[], offset = 0): boolean {
  return bytes.length >= offset + expected.length && expected.every((value, index) => bytes[offset + index] === value);
}

function readUint16(bytes: Uint8Array, offset: number): number {
  return (bytes[offset] ?? 0) * 0x100 + (bytes[offset + 1] ?? 0);
}

function readUint32(bytes: Uint8Array, offset: number): number {
  return readUint16(bytes, offset) * 0x10000 + readUint16(bytes, offset + 2);
}

function isFrameMarker(marker: number): boolean {
  return marker >= 0xc0 && marker <= 0xcf && !JPEG_NOT_A_FRAME.has(marker);
}

function readPng(bytes: Uint8Array): ImageSignature | null {
  if (!startsWith(bytes, PNG_SIGNATURE) || bytes.length < PNG_IHDR_END) return null;
  // The first chunk of every PNG is IHDR, and it holds the size.
  if (readUint32(bytes, 8) !== PNG_IHDR_DATA_LENGTH || !startsWith(bytes, PNG_IHDR_TYPE, 12)) return null;

  const width = readUint32(bytes, 16);
  const height = readUint32(bytes, 20);
  return width > 0 && height > 0 ? { mimeType: "image/png", width, height } : null;
}

// Walks the segments until the frame header (SOFn), which holds the size. A scan or the end of the
// image before any frame header, a segment that does not fit, or a missing marker prefix is not a JPEG.
function readJpeg(bytes: Uint8Array): ImageSignature | null {
  if (!startsWith(bytes, JPEG_SIGNATURE)) return null;

  let offset = JPEG_SIGNATURE.length - 1;
  while (offset + JPEG_MARKER_AND_LENGTH_SIZE <= bytes.length) {
    if (bytes[offset] !== JPEG_MARKER_PREFIX) return null;
    const marker = bytes[offset + 1] ?? 0;
    if (marker === JPEG_FILL_BYTE) {
      offset += 1;
      continue;
    }
    if (marker === JPEG_START_OF_SCAN || marker === JPEG_END_OF_IMAGE || marker === 0x00) return null;

    if (isFrameMarker(marker)) {
      if (offset + JPEG_FRAME_HEADER_SIZE > bytes.length) return null;
      const height = readUint16(bytes, offset + 5);
      const width = readUint16(bytes, offset + 7);
      return width > 0 && height > 0 ? { mimeType: "image/jpeg", width, height } : null;
    }

    const segmentLength = readUint16(bytes, offset + 2);
    if (segmentLength < 2) return null;
    offset += 2 + segmentLength;
  }
  return null;
}

/**
 * Recognises a PNG or a JPEG by its content and reads its size, or answers `null` for anything
 * else: SVG, GIF, WebP, text renamed to `.png`, a file cut short. It never decodes the image and
 * never throws, whatever the bytes are.
 */
export function readImageSignature(bytes: Uint8Array): ImageSignature | null {
  return readPng(bytes) ?? readJpeg(bytes);
}

files.server/files/systemOpener.ts:
import { spawn, type ChildProcess, type SpawnOptions } from "node:child_process";
import path from "node:path";

/** The computer could not open the file or the folder; `cause` has the operating system error. */
export class SystemOpenError extends Error {
  constructor(message: string, options?: { cause?: unknown }) {
    super(message, options);
    this.name = "SystemOpenError";
  }
}

/** Opens a file the app saved with the program the computer chose for it, or shows it in its folder. */
export interface SystemOpener {
  /** Opens the file in the default reader. Rejects with `SystemOpenError` when the system cannot. */
  openFile(filePath: string): Promise<void>;
  /** Opens the folder with the file selected (the folder alone on Linux). Rejects with `SystemOpenError`. */
  revealFile(filePath: string): Promise<void>;
}

export type SpawnProcess = (command: string, args: string[], options: SpawnOptions) => ChildProcess;

export interface SystemOpenerOptions {
  platform?: NodeJS.Platform;
  /** Starts a program; tests swap it for a fake. */
  spawnProcess?: SpawnProcess;
}

// How long `open` / `xdg-open` may run before the launch counts as done. They hand the file to
// the program that shows it and exit at once; a slow one has started and is left alone.
const EXIT_WAIT_MS = 3000;

interface Launch {
  command: string;
  args: string[];
  /** Windows needs the argument of `/select,` quoted by hand; Node would quote it as a whole. */
  verbatimArguments?: boolean;
  /** `explorer.exe` exits with 1 even when it worked, so only a failure to start counts for it. */
  exitCodeMeansFailure: boolean;
}

function windowsLaunch(action: "open" | "reveal", filePath: string): Launch {
  if (action === "open") {
    return { command: "explorer.exe", args: [filePath], exitCodeMeansFailure: false };
  }
  // The path sits between quotes in a command line that Node passes on as it is. Windows
  // never allows a quote in a path, so one here is refused instead of escaped.
  if (filePath.includes('"')) {
    throw new SystemOpenError("The path has a quote and cannot be selected in Explorer.");
  }
  return { command: "explorer.exe", args: [`/select,"${filePath}"`], verbatimArguments: true, exitCodeMeansFailure: false };
}

function unixLaunch(platform: NodeJS.Platform, action: "open" | "reveal", filePath: string): Launch {
  if (platform === "darwin") {
    return { command: "open", args: action === "open" ? [filePath] : ["-R", filePath], exitCodeMeansFailure: true };
  }
  // xdg-open cannot select a file: the folder is what it shows.
  return { command: "xdg-open", args: [action === "open" ? filePath : path.dirname(filePath)], exitCodeMeansFailure: true };
}

function buildLaunch(platform: NodeJS.Platform, action: "open" | "reveal", filePath: string): Launch {
  return platform === "win32" ? windowsLaunch(action, filePath) : unixLaunch(platform, action, filePath);
}

function run(spawnProcess: SpawnProcess, launch: Launch): Promise<void> {
  return new Promise<void>((resolve, reject) => {
    const options: SpawnOptions = { stdio: "ignore", detached: true, windowsVerbatimArguments: launch.verbatimArguments };
    let child: ChildProcess;
    try {
      child = spawnProcess(launch.command, launch.args, options);
    } catch (error) {
      reject(new SystemOpenError(`Could not start ${launch.command}.`, { cause: error }));
      return;
    }

    let settled = false;
    const finish = (error?: SystemOpenError): void => {
      if (settled) {
        return;
      }
      settled = true;
      clearTimeout(waitTimer);
      child.unref();
      if (error) {
        reject(error);
      } else {
        resolve();
      }
    };
    const waitTimer = setTimeout(() => finish(), EXIT_WAIT_MS);

    child.once("error", (cause) => finish(new SystemOpenError(`Could not start ${launch.command}.`, { cause })));
    child.once("exit", (code) => {
      finish(
        launch.exitCodeMeansFailure && code !== 0
          ? new SystemOpenError(`${launch.command} exited with code ${code ?? "none"}.`)
          : undefined,
      );
    });
    if (!launch.exitCodeMeansFailure) {
      child.once("spawn", () => finish());
    }
  });
}

/** The opener of the computer the app runs on. Programs start without a shell and with literal arguments. */
export function createSystemOpener({ platform = process.platform, spawnProcess = spawn }: SystemOpenerOptions = {}): SystemOpener {
  return {
    // `async` so a path that cannot be launched rejects instead of throwing.
    openFile: async (filePath) => run(spawnProcess, buildLaunch(platform, "open", filePath)),
    revealFile: async (filePath) => run(spawnProcess, buildLaunch(platform, "reveal", filePath)),
  };
}

files.server/http/errorHandler.ts:
import type { ErrorRequestHandler, RequestHandler, Response } from "express";
import { ZodError } from "zod";
import { DomainError } from "../services/domainError.ts";

/** Key used in `fields` for a validation issue that does not point at one field. */
export const ROOT_FIELD = "_root";

interface ErrorPayload {
  code: string;
  message: string;
  [key: string]: unknown;
}

function sendError(res: Response, status: number, payload: ErrorPayload): void {
  res.status(status).json({ error: payload });
}

function collectZodFields(error: ZodError): Record<string, string> {
  const fields: Record<string, string> = {};
  for (const issue of error.issues) {
    const key = issue.path.length > 0 ? issue.path.join(".") : ROOT_FIELD;
    fields[key] ??= issue.message;
  }
  return fields;
}

// Errors raised by express.json carry a `type`; anything else with a 4xx status
// comes from the HTTP layer (aborted request, unsupported charset, ...).
function readHttpClientError(error: unknown): { status: number; type?: string } | null {
  if (typeof error !== "object" || error === null) {
    return null;
  }
  const { status, type } = error as { status?: unknown; type?: unknown };
  if (typeof status !== "number" || status < 400 || status >= 500) {
    return null;
  }
  return { status, type: typeof type === "string" ? type : undefined };
}

// Prisma reports an unusable database in different shapes: a TypeError when the
// file cannot be opened, a DriverAdapterError for a file that is not a database,
// and P1xxx / P2021 / P2022 when the connection or the schema is missing.
const DATABASE_ERROR_NAMES = new Set(["PrismaClientInitializationError", "DriverAdapterError"]);
const DATABASE_UNAVAILABLE_PRISMA_CODE = /^(?:P1\d{3}|P2021|P2022)$/;
const DATABASE_OPEN_FAILURE_MESSAGE = /cannot open database|unable to open database|database is locked/i;

function isDatabaseUnavailable(error: unknown): boolean {
  if (!(error instanceof Error)) {
    return false;
  }
  if (DATABASE_ERROR_NAMES.has(error.name)) {
    return true;
  }
  const { code } = error as { code?: unknown };
  if (error.name === "PrismaClientKnownRequestError" && typeof code === "string") {
    return DATABASE_UNAVAILABLE_PRISMA_CODE.test(code);
  }
  return DATABASE_OPEN_FAILURE_MESSAGE.test(error.message);
}

/** Fallback for any request no route answered. */
export const notFoundHandler: RequestHandler = (_req, res) => {
  sendError(res, 404, { code: "not_found", message: "Rota não encontrada." });
};

/**
 * Turns every failure into `{ error: { code, message, ... } }` (IF-010). Unexpected
 * errors are logged to stderr, which the Play captures, and never echoed back.
 */
export const errorHandler: ErrorRequestHandler = (error, _req, res, next) => {
  if (res.headersSent) {
    next(error);
    return;
  }

  if (error instanceof DomainError) {
    sendError(res, error.status, { ...error.details, code: error.code, message: error.message });
    return;
  }

  if (error instanceof ZodError) {
    sendError(res, 400, {
      code: "validation_failed",
      message: "Confira os campos destacados.",
      fields: collectZodFields(error),
    });
    return;
  }

  const clientError = readHttpClientError(error);
  if (clientError?.type === "entity.too.large") {
    sendError(res, 413, { code: "payload_too_large", message: "O conteúdo enviado é grande demais." });
    return;
  }
  if (clientError?.type === "entity.parse.failed") {
    sendError(res, 400, { code: "invalid_json", message: "O conteúdo enviado não é um JSON válido." });
    return;
  }
  if (clientError) {
    sendError(res, clientError.status, { code: "bad_request", message: "A requisição não pôde ser lida." });
    return;
  }

  if (isDatabaseUnavailable(error)) {
    console.error("[fitpulse] database unavailable:", error);
    sendError(res, 503, {
      code: "database_unavailable",
      message: "Não foi possível abrir os dados do FitPulse. Feche e abra o app de novo.",
    });
    return;
  }

  console.error("[fitpulse] unexpected error:", error);
  sendError(res, 500, { code: "internal_error", message: "Algo deu errado. Tente de novo." });
};

files.server/http/requestGuards.ts:
import type { RequestHandler } from "express";
import { DomainError } from "../services/domainError.ts";

// The Host header, not the socket, is what a DNS-rebinding page cannot fake: a
// page served from evil.example that resolves to 127.0.0.1 still sends
// `Host: evil.example:<port>`. The server only listens on its own ports, so the
// hostname is what needs checking.
const LOCAL_HOST = /^(?:127\.0\.0\.1|localhost)(?::\d{1,5})?$/i;

const WRITE_METHODS = new Set(["POST", "PUT", "PATCH"]);

/** Answers 403 `host_not_allowed` unless the request addressed 127.0.0.1 or localhost. */
export const requireLocalHost: RequestHandler = (req, _res, next) => {
  const host = req.headers.host;
  if (host === undefined || !LOCAL_HOST.test(host)) {
    next(new DomainError(403, "host_not_allowed", "O FitPulse só responde neste computador."));
    return;
  }
  next();
};

function isJsonContentType(header: string | undefined): boolean {
  const mediaType = header?.split(";", 1)[0]?.trim().toLowerCase();
  return mediaType === "application/json";
}

/**
 * Writes must declare `application/json`, even when they carry no body. A page on
 * another origin cannot send that type without a CORS preflight, and the app
 * answers none, so a cross-site form or `no-cors` fetch cannot reach a write route.
 * `req.is()` is not used because it returns null for a body-less request even when
 * the header is present, so it cannot tell that case from a wrong type.
 */
export const requireJsonWrites: RequestHandler = (req, _res, next) => {
  if (WRITE_METHODS.has(req.method) && !isJsonContentType(req.headers["content-type"])) {
    next(new DomainError(415, "json_required", "Envie o conteúdo como JSON."));
    return;
  }
  next();
};

files.server/main.ts:
import os from "node:os";
import path from "node:path";
import { createApp, resolveBackendPort } from "./app.ts";
import { createPrismaClient } from "./db/prismaClient.ts";
import { createSystemOpener } from "./files/systemOpener.ts";

// Loopback only (RULE-dm-16): other machines on the network must not reach the API.
const HOST = "127.0.0.1";
const FORCED_EXIT_AFTER_MS = 5000;

const port = resolveBackendPort();
const prisma = createPrismaClient();
const app = createApp({
  prisma,
  now: () => new Date(),
  downloadsDir: path.join(os.homedir(), "Downloads"),
  systemOpener: createSystemOpener(),
  backendPort: port,
});

const server = app.listen(port, HOST, () => {
  console.log(`[fitpulse] api listening on http://${HOST}:${port}`);
});

server.on("error", (error: NodeJS.ErrnoException) => {
  console.error(`[fitpulse] cannot listen on ${HOST}:${port}:`, error.message);
  process.exit(1);
});

let shuttingDown = false;

function shutdown(signal: string): void {
  if (shuttingDown) {
    return;
  }
  shuttingDown = true;
  console.log(`[fitpulse] ${signal} received, shutting down`);

  // A keep-alive connection must not hold the process open.
  setTimeout(() => process.exit(1), FORCED_EXIT_AFTER_MS).unref();
  server.close(() => {
    prisma.$disconnect().then(
      () => process.exit(0),
      (error: unknown) => {
        console.error("[fitpulse] failed to disconnect the database:", error);
        process.exit(1);
      },
    );
  });
  server.closeAllConnections();
}

process.on("SIGTERM", () => shutdown("SIGTERM"));
process.on("SIGINT", () => shutdown("SIGINT"));

files.server/questionnaire/questionnaireClient:
/*
 * Browser side of the questionnaire file a client opens offline (RULE-ra-11).
 * Plain JavaScript, no network, no storage: the server inlines this file next to the catalog
 * (a JSON block with the id "fitpulse-data"). Text only ever goes in through `textContent`,
 * so a hostile company or brand name stays text.
 * Money and number masks are a port of `shared/format/money.ts` and the calculator block of
 * the app; `tests/unit/questionnaireFile.test.ts` keeps them in step.
 */
(function () {
  "use strict";

  const MONEY_MAX_DIGITS = 13;
  const MONEY_MAX_CENTS = 10 ** MONEY_MAX_DIGITS - 1;
  const NEW_CUSTOMERS_MAX = 1000000;
  const MARGIN_MAX = 100;

  const hasOwn = (object, key) => Object.prototype.hasOwnProperty.call(object, key);

  /* ---------- Masks (port of shared/format/money.ts) ---------- */

  function groupThousands(digits) {
    return digits.replace(/\B(?=(\d{3})+(?!\d))/g, ".");
  }

  function formatMoney(cents) {
    const remainder = String(cents % 100);
    return "R$ " + groupThousands(String(Math.floor(cents / 100))) + "," + (remainder.length < 2 ? "0" + remainder : remainder);
  }

  const MONEY_MASK_LENGTH = formatMoney(MONEY_MAX_CENTS).length;

  function stripLeadingZeros(digits) {
    return digits.replace(/^0+(?=\d)/, "");
  }

  function digitsAfter(text, caret) {
    return (text.slice(caret).match(/\d/g) || []).length;
  }

  function caretWithDigitsAfter(masked, digitsToTheRight) {
    if (digitsToTheRight <= 0) return masked.length;
    let seen = 0;
    for (let index = masked.length - 1; index >= 0; index -= 1) {
      if (/\d/.test(masked.charAt(index))) {
        seen += 1;
        if (seen === digitsToTheRight) return index;
      }
    }
    return 0;
  }

  function maskedFromDigits(digits) {
    if (digits === "") return { value: "", cents: null };
    const cents = Number(digits);
    return { value: formatMoney(cents), cents: cents };
  }

  // Typed digits fill the cents from the right ("12" -> "R$ 0,12") and the caret keeps its place.
  function maskMoney(rawValue, caret, previous) {
    let raw = rawValue;
    let position = Math.min(Math.max(caret === undefined ? raw.length : caret, 0), raw.length);

    const separatorWasDeleted =
      previous !== undefined && raw.length < previous.length && raw.replace(/\D/g, "") === previous.replace(/\D/g, "");
    if (separatorWasDeleted) {
      const lastDigit = raw.slice(0, position).search(/\d(?!.*\d)/);
      if (lastDigit >= 0) {
        raw = raw.slice(0, lastDigit) + raw.slice(lastDigit + 1);
        position = lastDigit;
      }
    }

    const previousDigits = stripLeadingZeros((previous === undefined ? "" : previous).replace(/\D/g, ""));
    let digits = stripLeadingZeros(raw.replace(/\D/g, ""));
    if (digits.length > MONEY_MAX_DIGITS) {
      if (previous === undefined) {
        digits = digits.slice(0, MONEY_MAX_DIGITS);
      } else {
        const fallback = maskedFromDigits(previousDigits);
        return {
          value: fallback.value,
          cents: fallback.cents,
          caret: Math.max(Math.min(position - 1, fallback.value.length), 0),
        };
      }
    }
    const wasDeleted = previous !== undefined && raw.length < previous.length;
    if (wasDeleted && digits === "0" && previousDigits === "0") digits = "";

    const masked = maskedFromDigits(digits);
    return { value: masked.value, cents: masked.cents, caret: caretWithDigitsAfter(masked.value, digitsAfter(raw, position)) };
  }

  // A whole number typed by the client; null when empty or above the limit.
  function readWhole(text, max) {
    if (text === "") return null;
    const value = Number(text);
    return Number.isSafeInteger(value) && value <= max ? value : null;
  }

  const isCount = (value) => typeof value === "number" && Number.isInteger(value) && value >= 0;

  /* ---------- Answers and file (pure, shared with the unit test) ---------- */

  function emptyCalculator() {
    return {
      spendMode: null,
      spendParts: {},
      spendRange: null,
      newCustomersMode: null,
      newCustomers: null,
      newCustomersRange: null,
      averagePurchaseCents: null,
      purchasesPerYear: null,
      relationshipLength: null,
      marginPercent: null,
    };
  }

  // "Não sei" is a complete answer; exact and range need their own value.
  function isEntryComplete(mode, hasExact, hasRange) {
    if (mode === "unknown") return true;
    if (mode === "exact") return hasExact;
    if (mode === "range") return hasRange;
    return false;
  }

  function isCalculatorComplete(calc) {
    const margin = calc.marginPercent;
    return (
      isEntryComplete(calc.spendMode, Object.keys(calc.spendParts).length > 0, calc.spendRange !== null) &&
      isEntryComplete(calc.newCustomersMode, isCount(calc.newCustomers), calc.newCustomersRange !== null) &&
      isCount(calc.averagePurchaseCents) &&
      calc.purchasesPerYear !== null &&
      calc.relationshipLength !== null &&
      isCount(margin) &&
      margin <= MARGIN_MAX
    );
  }

  // Block 1 is the calculator; the others are answered when every question has a value.
  function isBlockAnswered(data, state, blockNumber) {
    if (blockNumber === 1) return isCalculatorComplete(state.calc);
    return data.questions.filter((q) => q.block === blockNumber).every((q) => hasOwn(state.answers, q.id));
  }

  function countAnsweredBlocks(data, state) {
    return data.blocks.filter((info) => isBlockAnswered(data, state, info.number)).length;
  }

  // Only the values of the mode the client picked travel in the file.
  function readCalculator(data, calc) {
    const out = {};
    if (calc.spendMode) {
      out.spendMode = calc.spendMode;
      if (calc.spendMode === "exact") {
        const parts = {};
        data.calculator.spendParts.forEach((part) => {
          if (isCount(calc.spendParts[part.key])) parts[part.key] = calc.spendParts[part.key];
        });
        if (Object.keys(parts).length > 0) out.spendParts = parts;
      } else if (calc.spendMode === "range" && calc.spendRange) {
        out.spendRange = calc.spendRange;
      }
    }
    if (calc.newCustomersMode) {
      out.newCustomersMode = calc.newCustomersMode;
      if (calc.newCustomersMode === "exact" && isCount(calc.newCustomers)) out.newCustomers = calc.newCustomers;
      else if (calc.newCustomersMode === "range" && calc.newCustomersRange) out.newCustomersRange = calc.newCustomersRange;
    }
    if (isCount(calc.averagePurchaseCents)) out.averagePurchaseCents = calc.averagePurchaseCents;
    if (calc.purchasesPerYear) out.purchasesPerYear = calc.purchasesPerYear;
    if (calc.relationshipLength) out.relationshipLength = calc.relationshipLength;
    if (isCount(calc.marginPercent) && calc.marginPercent <= MARGIN_MAX) out.marginPercent = calc.marginPercent;
    return out;
  }

  // The `.fitpulse` file: answers and calculator in the shape of the diagnosis PATCH.
  function buildAnswersFile(data, state, now) {
    const answers = {};
    data.questions.forEach((q) => {
      if (hasOwn(state.answers, q.id)) answers[q.id] = state.answers[q.id];
    });
    return {
      format: data.format,
      formatVersion: data.formatVersion,
      questionnaireVersion: data.questionnaireVersion,
      company: { id: data.company.id, name: data.company.name },
      savedAt: now.toISOString(),
      answers: answers,
      calculator: readCalculator(data, state.calc),
    };
  }

  // After saving: who gets the file. Without a brand it is "o seu consultor".
  function savedInstruction(brand) {
    let text = "Agora envie o arquivo para " + (brand && brand.name ? brand.name : "o seu consultor");
    if (brand && brand.phone) text += " pelo WhatsApp " + brand.phone;
    if (brand && brand.email) text += (brand.phone ? " ou" : "") + " por e-mail para " + brand.email;
    return text + ". Ele importa as respostas no FitPulse e revisa com você.";
  }

  const hook = typeof globalThis === "object" ? globalThis.__fitpulseQuestionnaireTestHook : undefined;
  if (typeof hook === "function") {
    hook({ maskMoney, readWhole, formatMoney, emptyCalculator, isBlockAnswered, countAnsweredBlocks, buildAnswersFile, savedInstruction });
    return;
  }

  /* ---------- Screen ---------- */

  function el(tag, props, children) {
    const node = document.createElement(tag);
    Object.keys(props || {}).forEach((key) => {
      const value = props[key];
      if (value === null || value === undefined || value === false) return;
      if (key === "text") node.textContent = value;
      else if (key === "className") node.className = value;
      else node.setAttribute(key, value === true ? "" : String(value));
    });
    (children || []).forEach((child) => {
      if (child) node.appendChild(typeof child === "string" ? document.createTextNode(child) : child);
    });
    return node;
  }

  function monogram(name) {
    const letters = (name || "").split(/\s+/).filter(Boolean).slice(0, 2).map((word) => word.charAt(0).toUpperCase());
    return letters.length > 0 ? letters.join("") : "FP";
  }

  function download(fileName, text) {
    const url = URL.createObjectURL(new Blob([text], { type: "application/octet-stream" }));
    const link = el("a", { href: url, download: fileName, style: "display:none" });
    document.body.appendChild(link);
    link.click();
    setTimeout(() => {
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
    }, 1000);
  }

  // What every screen shares: the catalog, what the client answered so far and how to move.
  function createApp(root, data) {
    const app = {
      root: root,
      data: data,
      brand: data.brand,
      totalBlocks: data.blocks.length,
      state: { view: "block", block: 0, answers: {}, calc: emptyCalculator(), dirty: false },
      touch: () => {
        app.state.dirty = true;
      },
      go: (view, block) => {
        app.state.view = view;
        if (block !== undefined) app.state.block = block;
        renderApp(app);
      },
    };
    return app;
  }

  /* ----- Form controls ----- */

  function syncSelected(group) {
    group.querySelectorAll("label").forEach((label) => label.classList.toggle("selected", label.querySelector("input").checked));
  }

  function radioGroup(name, labelledBy, items, checkedKey, onPick, groupClass) {
    const group = el("div", { className: groupClass, role: "radiogroup", "aria-labelledby": labelledBy });
    items.forEach((item) => {
      const input = el("input", { type: "radio", name: name, value: item.key });
      input.checked = item.key === checkedKey;
      input.addEventListener("change", () => {
        onPick(item.key);
        syncSelected(group);
      });
      group.appendChild(el("label", { className: item.className }, [input, el("span", { text: item.label })]));
    });
    syncSelected(group);
    return group;
  }

  // Title row with the "?" button; the help text starts hidden.
  function titled(titleId, title, help) {
    const helpId = "help-" + titleId;
    const helpText = el("p", { className: "help-text", id: helpId, hidden: true, text: help });
    const toggle = el("button", { type: "button", className: "help-toggle", "aria-expanded": "false", "aria-controls": helpId, "aria-label": "Ajuda: " + title, text: "?" });
    toggle.addEventListener("click", () => {
      helpText.hidden = !helpText.hidden;
      toggle.setAttribute("aria-expanded", String(!helpText.hidden));
    });
    return [el("div", { className: "heading-row" }, [el("p", { className: "question-title", id: titleId, text: title }), toggle]), helpText];
  }

  function moneyInput(app, id, cents, labelProps, onCents) {
    const input = el("input", Object.assign({ id: id, className: "input mono", type: "text", inputmode: "decimal", autocomplete: "off", maxlength: MONEY_MASK_LENGTH, placeholder: "R$ 0,00" }, labelProps));
    let shown = isCount(cents) ? formatMoney(cents) : "";
    input.value = shown;
    input.addEventListener("input", () => {
      const masked = maskMoney(input.value, input.selectionStart === null ? undefined : input.selectionStart, shown);
      shown = masked.value;
      input.value = masked.value;
      try {
        input.setSelectionRange(masked.caret, masked.caret);
      } catch (error) {
        /* a browser that refuses to place the caret keeps it at the end */
      }
      app.touch();
      onCents(masked.cents);
    });
    return input;
  }

  // Digits only; a value above the limit shows the error and is not kept. `spec`: id, value, max, placeholder, errorText, labelledBy.
  function wholeInput(app, spec, onValue) {
    const error = el("p", { className: "field-error", id: spec.id + "-error" });
    const input = el("input", { id: spec.id, className: "input mono", type: "text", inputmode: "numeric", autocomplete: "off", maxlength: String(spec.max).length, placeholder: spec.placeholder, "aria-labelledby": spec.labelledBy, "aria-describedby": spec.id + "-error" });
    input.value = isCount(spec.value) ? String(spec.value) : "";
    input.addEventListener("input", () => {
      const digits = input.value.replace(/\D/g, "");
      const parsed = readWhole(digits, spec.max);
      const invalid = digits !== "" && parsed === null;
      input.value = digits;
      input.setAttribute("aria-invalid", String(invalid));
      error.textContent = invalid ? spec.errorText : "";
      app.touch();
      onValue(parsed);
    });
    return el("div", { className: "field narrow" }, [input, error]);
  }

  function optionSelect(app, labelledBy, placeholder, options, value, onValue) {
    const select = el("select", { "aria-labelledby": labelledBy }, [el("option", { value: "", text: placeholder })]);
    options.forEach((option) => select.appendChild(el("option", { value: option.key, text: option.label })));
    select.value = value || "";
    select.addEventListener("change", () => {
      app.touch();
      onValue(select.value === "" ? null : select.value);
    });
    return el("div", { className: "field medium" }, [select]);
  }

  function questionItem(app, question) {
    const answers = app.state.answers;
    const titleId = "q-" + question.id;
    const items = question.options.map((option) => ({ key: String(option.value), label: option.label, className: "choice" }));
    if (question.unknownLabel !== null) items.push({ key: "unknown", label: question.unknownLabel, className: "choice unknown" });
    let current = null;
    if (hasOwn(answers, question.id)) current = answers[question.id] === null ? "unknown" : String(answers[question.id]);
    const group = radioGroup("answer-" + question.id, titleId, items, current, (key) => {
      answers[question.id] = key === "unknown" ? null : Number(key);
      app.touch();
    }, "choices");
    return el("div", { className: "question" }, titled(titleId, question.text, question.help).concat([group]));
  }

  /* ----- Block 1: the six calculator fields ----- */

  function calculatorItem(app, fieldKey, buildBody) {
    const titleId = "calc-" + fieldKey;
    const copy = app.data.calculator.fields[fieldKey];
    return el("div", { className: "question", "data-field": fieldKey }, titled(titleId, copy.label, copy.help).concat(buildBody(titleId)));
  }

  // Mode radios plus the area for the picked mode ("sei os valores", "sei mais ou menos", "não sei").
  function entryItem(app, fieldKey, modes, modeKey, fillArea) {
    return calculatorItem(app, fieldKey, (titleId) => {
      const calc = app.state.calc;
      const area = el("div");
      const refill = () => {
        area.textContent = "";
        fillArea(app, titleId).forEach((node) => area.appendChild(node));
      };
      const items = modes.map((mode) => ({ key: mode.key, label: mode.label, className: "mode-option" }));
      const group = radioGroup("mode-" + fieldKey, titleId, items, calc[modeKey], (mode) => {
        calc[modeKey] = mode;
        app.touch();
        refill();
      }, "mode-row");
      refill();
      return [group, area];
    });
  }

  function spendExactFields(app) {
    const calc = app.state.calc;
    const total = el("output");
    const showTotal = () => {
      const values = Object.keys(calc.spendParts).map((key) => calc.spendParts[key]);
      total.textContent = formatMoney(values.reduce((sum, value) => sum + value, 0));
    };
    const fields = app.data.calculator.spendParts.map((part) => {
      const id = "spend-" + part.key;
      const input = moneyInput(app, id, calc.spendParts[part.key], {}, (cents) => {
        if (cents === null) delete calc.spendParts[part.key];
        else calc.spendParts[part.key] = cents;
        showTotal();
      });
      return el("div", { className: "field" }, [el("label", { for: id, text: part.label }), input]);
    });
    showTotal();
    return [
      el("div", { className: "field-grid" }, fields.concat([el("p", { className: "total-row" }, [el("span", { text: "Total em 3 meses" }), total])])),
      el("p", { className: "muted", text: "Deixe em branco o que você não usa. Contar só o anúncio deixa o custo do cliente menor do que é." }),
    ];
  }

  function spendArea(app, titleId) {
    const calc = app.state.calc;
    if (calc.spendMode === "range") {
      return [optionSelect(app, titleId, "Escolha uma faixa", app.data.calculator.spendRanges, calc.spendRange, (value) => { calc.spendRange = value; })];
    }
    return calc.spendMode === "exact" ? spendExactFields(app) : [];
  }

  function newCustomersArea(app, titleId) {
    const calc = app.state.calc;
    if (calc.newCustomersMode === "range") {
      return [optionSelect(app, titleId, "Escolha uma faixa", app.data.calculator.newCustomersRanges, calc.newCustomersRange, (value) => { calc.newCustomersRange = value; })];
    }
    if (calc.newCustomersMode !== "exact") return [];
    const spec = { id: "new-customers", value: calc.newCustomers, max: NEW_CUSTOMERS_MAX, placeholder: "Ex.: 40", errorText: "Use um número de 0 a 1.000.000.", labelledBy: titleId };
    return [wholeInput(app, spec, (value) => { calc.newCustomers = value; })];
  }

  function renderCalculator(app) {
    const calc = app.state.calc;
    const options = app.data.calculator;
    const marginSpec = (titleId) => ({ id: "margin", value: calc.marginPercent, max: MARGIN_MAX, placeholder: "Ex.: 35", errorText: "Use um número de 0 a 100.", labelledBy: titleId });
    return el("div", {}, [
      entryItem(app, "spend", options.spendModes, "spendMode", spendArea),
      entryItem(app, "newCustomers", options.newCustomersModes, "newCustomersMode", newCustomersArea),
      calculatorItem(app, "averagePurchase", (titleId) => [
        el("div", { className: "field narrow" }, [moneyInput(app, "average-purchase", calc.averagePurchaseCents, { "aria-labelledby": titleId }, (cents) => { calc.averagePurchaseCents = cents; })]),
      ]),
      calculatorItem(app, "purchasesPerYear", (titleId) => [optionSelect(app, titleId, "Escolha", options.purchasesPerYear, calc.purchasesPerYear, (value) => { calc.purchasesPerYear = value; })]),
      calculatorItem(app, "relationshipLength", (titleId) => [optionSelect(app, titleId, "Escolha", options.relationshipLength, calc.relationshipLength, (value) => { calc.relationshipLength = value; })]),
      calculatorItem(app, "margin", (titleId) => [
        wholeInput(app, marginSpec(titleId), (value) => { calc.marginPercent = value; }),
        el("p", { className: "muted", text: "Digite só o número: 35 quer dizer que sobram R$ 35." }),
      ]),
    ]);
  }

  /* ----- Screens ----- */

  function renderHead(app) {
    const brand = app.brand;
    const name = brand && brand.name ? brand.name : "Seu consultor";
    const contact = brand ? [brand.phone, brand.email].filter(Boolean).join(" · ") : "";
    const mark = el("span", { className: "brand-mark" });
    if (brand && brand.logo) mark.appendChild(el("img", { src: brand.logo, alt: "" }));
    else mark.textContent = monogram(brand ? brand.name : "");
    return el("header", { className: "client-head" }, [
      mark,
      el("div", {}, [el("div", { className: "brand-name", text: name }), el("div", { className: "muted", text: contact || "Questionário do FitPulse" })]),
    ]);
  }

  function renderIntro(app) {
    return [
      el("h1", { className: "title", text: "Questionário de crescimento" }),
      el("p", { className: "subtitle", text: app.data.company.name + " · leva uns 12 minutos" }),
    ];
  }

  function renderNotice(app) {
    return el("div", { className: "notice", role: "note" }, [el("span", { className: "notice-icon", "aria-hidden": "true", text: "!" }), el("span", { text: app.data.copy.desktopNotice })]);
  }

  function renderRail(app) {
    const state = app.state;
    const nav = el("nav", { className: "rail", "aria-label": "Blocos do questionário" });
    app.data.blocks.forEach((info, index) => {
      const answered = isBlockAnswered(app.data, state, info.number);
      const current = state.view === "block" && index === state.block;
      const link = el("a", {
        href: "#bloco-" + info.number,
        className: current ? "current" : answered ? "done" : "",
        "aria-label": "Bloco " + info.number + ": " + info.title + (answered ? " (respondido)" : ""),
        "aria-current": current ? "step" : null,
      });
      link.addEventListener("click", (event) => {
        event.preventDefault();
        app.go("block", index);
      });
      nav.appendChild(link);
    });
    return nav;
  }

  function renderBlock(app) {
    const state = app.state;
    const info = app.data.blocks[state.block];
    const children = [
      el("h2", { tabindex: "-1", "data-screen-title": "", text: info.number + ". " + info.title }),
      el("p", { className: "intro", text: info.intro }),
    ];
    if (info.number === 1) children.push(renderCalculator(app));
    else app.data.questions.filter((q) => q.block === info.number).forEach((q) => children.push(questionItem(app, q)));

    const back = el("button", { type: "button", className: "btn", text: "Voltar" });
    back.addEventListener("click", () => app.go("block", state.block - 1));
    const last = state.block === app.totalBlocks - 1;
    const next = el("button", { type: "button", className: "btn btn-primary", text: last ? "Revisar" : "Próximo bloco" });
    next.addEventListener("click", () => (last ? app.go("review") : app.go("block", state.block + 1)));
    children.push(el("div", { className: "actions" }, [state.block > 0 ? back : null, next]));
    return el("section", { className: "panel" }, children);
  }

  // A block that is answered shows a chip; one that is not links back to it.
  function reviewRow(app, info, index) {
    let status;
    if (isBlockAnswered(app.data, app.state, info.number)) {
      status = el("span", { className: "chip", text: "Respondido" });
    } else {
      status = el("a", { className: "link", href: "#bloco-" + info.number, "aria-label": "Responder o bloco " + info.number + ": " + info.title, text: "Responder" });
      status.addEventListener("click", (event) => {
        event.preventDefault();
        app.go("block", index);
      });
    }
    return el("li", {}, [el("span", { text: info.number + ". " + info.title }), status]);
  }

  function renderReview(app) {
    const answered = countAnsweredBlocks(app.data, app.state);
    const summary = answered + " de " + app.totalBlocks + " blocos respondidos." + (answered < app.totalBlocks ? " Você pode salvar assim mesmo; o consultor vê o que ficou faltando." : "");
    const back = el("button", { type: "button", className: "btn", text: "Voltar" });
    back.addEventListener("click", () => app.go("block", app.totalBlocks - 1));
    const save = el("button", { type: "button", className: "btn btn-gold", text: "Salvar minhas respostas" });
    save.addEventListener("click", () => saveAnswers(app));
    return el("section", { className: "panel" }, [
      el("h2", { tabindex: "-1", "data-screen-title": "", text: "Revise e salve" }),
      el("p", { className: "intro", text: summary }),
      el("ul", { className: "review-rows" }, app.data.blocks.map((info, index) => reviewRow(app, info, index))),
      el("div", { className: "actions" }, [back, save]),
    ]);
  }

  function renderSaved(app) {
    const again = el("button", { type: "button", className: "btn", text: "Baixar de novo" });
    again.addEventListener("click", () => writeFile(app));
    const edit = el("button", { type: "button", className: "btn", text: "Voltar às respostas" });
    edit.addEventListener("click", () => app.go("review"));
    return el("section", { className: "panel saved", role: "status" }, [
      el("h2", { tabindex: "-1", "data-screen-title": "", text: "Respostas salvas" }),
      el("p", {}, ["O arquivo foi para a pasta de downloads deste computador: ", el("span", { className: "file-path", text: app.data.answersFileName })]),
      el("p", { text: savedInstruction(app.brand) }),
      el("div", { className: "actions" }, [again, edit]),
    ]);
  }

  function writeFile(app) {
    download(app.data.answersFileName, JSON.stringify(buildAnswersFile(app.data, app.state, new Date()), null, 2));
  }

  function saveAnswers(app) {
    writeFile(app);
    app.state.dirty = false;
    app.go("saved");
  }

  function renderApp(app) {
    const state = app.state;
    app.root.textContent = "";
    const shell = el("div", { className: "shell" }, [renderHead(app)].concat(renderIntro(app)));
    if (state.view === "saved") {
      shell.appendChild(renderSaved(app));
    } else {
      const progress = state.view === "review" ? "Revisão" : "Bloco " + (state.block + 1) + " de " + app.totalBlocks + " · " + app.data.blocks[state.block].title;
      shell.appendChild(renderNotice(app));
      shell.appendChild(renderRail(app));
      shell.appendChild(el("p", { className: "progress", text: progress }));
      shell.appendChild(state.view === "review" ? renderReview(app) : renderBlock(app));
    }
    app.root.appendChild(shell);
    const heading = app.root.querySelector("[data-screen-title]");
    if (heading) heading.focus({ preventScroll: true });
    window.scrollTo(0, 0);
  }

  function boot() {
    const root = document.getElementById("app");
    let data = null;
    try {
      data = JSON.parse(document.getElementById("fitpulse-data").textContent);
    } catch (error) {
      data = null;
    }
    if (data === null) {
      root.appendChild(el("p", { className: "fallback", text: "Este arquivo está incompleto. Peça um novo questionário a quem o enviou." }));
      return;
    }
    const app = createApp(root, data);
    // The approved warning says the answers are lost when the page closes before saving.
    window.addEventListener("beforeunload", (event) => {
      if (!app.state.dirty) return;
      event.preventDefault();
      event.returnValue = "";
    });
    renderApp(app);
  }

  boot();
})();

files.server/questionnaire/questionnaireFile.t:
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import {
  CALCULATOR_FIELDS,
  NEW_CUSTOMERS_MODE_OPTIONS,
  NEW_CUSTOMERS_RANGE_OPTIONS,
  PURCHASES_PER_YEAR_OPTIONS,
  RELATIONSHIP_LENGTH_OPTIONS,
  SPEND_MODE_OPTIONS,
  SPEND_PART_OPTIONS,
  SPEND_RANGE_OPTIONS,
} from "../../shared/content/calculatorOptions.ts";
import { BLOCKS, QUESTION_BANK } from "../../shared/content/questionBank.ts";

/** Marker and versions of the `.fitpulse` answers file the client saves (IF-004). */
export const ANSWERS_FILE_FORMAT = "fitpulse-answers";
export const ANSWERS_FILE_FORMAT_VERSION = 1;
/** Bumped when a question changes meaning or leaves the catalog: older answers no longer fit. */
export const QUESTIONNAIRE_VERSION = 1;
export const ANSWERS_FILE_EXTENSION = ".fitpulse";

/** Approved notice at the top of the file (PRD, "Conteúdo v2", item 3). */
export const QUESTIONNAIRE_DESKTOP_NOTICE =
  "Feito para abrir no computador. No celular, o formulário pode não funcionar direito. Se estiver no celular, abra este arquivo no computador. Responda tudo de uma vez: se fechar esta página antes de salvar, as respostas se perdem.";

// RULE-ra-11: no request of any kind leaves the page. `img-src data:` is for the brand logo.
const CONTENT_SECURITY_POLICY =
  "default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data:; form-action 'none'; base-uri 'none'";

const MAX_SLUG_LENGTH = 60;
const FALLBACK_COMPANY_NAME = "sua empresa";
const LOGO_DATA_URL = /^data:image\/(?:png|jpeg|webp);base64,[A-Za-z0-9+/]+={0,2}$/;

export interface QuestionnaireBrand {
  name: string | null;
  /** Phone as it is shown to people, for example "(11) 91234-5678". */
  phone: string | null;
  email: string | null;
  /** `data:image/png|jpeg|webp;base64,…`; any other value is left out of the file. */
  logoDataUrl: string | null;
}

export interface QuestionnaireFileInput {
  /** The only company the file knows: its id (to match the answers on import) and its name. */
  company: { id: string; name: string };
  /** Who delivers the work; `null` when no brand is set. */
  brand: QuestionnaireBrand | null;
  sentAt: Date;
}

export interface QuestionnaireFile {
  html: string;
  /** `{empresa}-questionario-{AAAA-MM-DD}.html` */
  fileName: string;
  /** `respostas-{empresa}.fitpulse`, the name the client's browser saves the answers under. */
  answersFileName: string;
}

interface EmbeddedBrand {
  name: string | null;
  phone: string | null;
  email: string | null;
  logo: string | null;
}

function cleanText(value: string | null | undefined): string | null {
  const text = value?.trim() ?? "";
  return text === "" ? null : text;
}

function toEmbeddedBrand(brand: QuestionnaireBrand | null): EmbeddedBrand | null {
  if (brand === null) return null;
  const logo = brand.logoDataUrl !== null && LOGO_DATA_URL.test(brand.logoDataUrl) ? brand.logoDataUrl : null;
  const embedded = { name: cleanText(brand.name), phone: cleanText(brand.phone), email: cleanText(brand.email), logo };
  return Object.values(embedded).every((value) => value === null) ? null : embedded;
}

/** Lowercase letters, digits and hyphens only: safe in a file name on every system. */
export function slugifyForFileName(text: string): string {
  const slug = text
    .normalize("NFD")
    .replace(/\p{M}/gu, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+/, "")
    .slice(0, MAX_SLUG_LENGTH)
    .replace(/-+$/, "");
  return slug === "" ? "empresa" : slug;
}

function formatLocalIsoDate(date: Date): string {
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${date.getFullYear()}-${month}-${day}`;
}

export function questionnaireFileName(companyName: string, sentAt: Date): string {
  return `${slugifyForFileName(companyName)}-questionario-${formatLocalIsoDate(sentAt)}.html`;
}

export function answersFileName(companyName: string): string {
  return `respostas-${slugifyForFileName(companyName)}${ANSWERS_FILE_EXTENSION}`;
}

/** The approved message the consultant copies to the client (PRD, "Conteúdo v2", item 3). */
export function buildClientMessage(companyName: string, brandName: string | null): string {
  const message =
    `Olá! Segue o questionário do FitPulse para a ${companyName}. Abra o arquivo no computador ` +
    '(no celular ele pode não funcionar), responda com calma e, no fim, clique em "Salvar minhas respostas". ' +
    "Depois me envie o arquivo que for salvo. Leva uns 12 minutos.";
  const signature = cleanText(brandName);
  return signature === null ? message : `${message}\n${signature}`;
}

/** JSON that can sit inside `<script>`: nothing in it can close the tag or start a comment (\p{Zl} and \p{Zp} are U+2028 and U+2029). */
export function escapeJsonForHtml(value: unknown): string {
  return JSON.stringify(value).replace(
    /[<>&\p{Zl}\p{Zp}]/gu,
    (character) => `\\u${character.charCodeAt(0).toString(16).padStart(4, "0")}`,
  );
}

function escapeHtml(text: string): string {
  return text.replace(/[&<>"']/g, (character) => `&#${character.charCodeAt(0)};`);
}

function buildEmbeddedData(input: QuestionnaireFileInput, companyName: string) {
  return {
    format: ANSWERS_FILE_FORMAT,
    formatVersion: ANSWERS_FILE_FORMAT_VERSION,
    questionnaireVersion: QUESTIONNAIRE_VERSION,
    company: { id: input.company.id, name: companyName },
    answersFileName: answersFileName(companyName),
    brand: toEmbeddedBrand(input.brand),
    copy: { desktopNotice: QUESTIONNAIRE_DESKTOP_NOTICE },
    blocks: BLOCKS.map(({ number, id, title, intro }) => ({ number, id, title, intro })),
    // The dimension stays out: it only matters to the scoring, not to the person answering.
    questions: QUESTION_BANK.map(({ id, block, text, help, options, unknownLabel }) => ({
      id,
      block,
      text,
      help,
      options,
      unknownLabel,
    })),
    calculator: {
      fields: CALCULATOR_FIELDS,
      spendParts: SPEND_PART_OPTIONS,
      spendModes: SPEND_MODE_OPTIONS,
      spendRanges: SPEND_RANGE_OPTIONS,
      newCustomersModes: NEW_CUSTOMERS_MODE_OPTIONS,
      newCustomersRanges: NEW_CUSTOMERS_RANGE_OPTIONS,
      purchasesPerYear: PURCHASES_PER_YEAR_OPTIONS,
      relationshipLength: RELATIONSHIP_LENGTH_OPTIONS,
    },
  };
}

interface InlineAssets {
  css: string;
  script: string;
}

let cachedAssets: InlineAssets | undefined;

// Read when the first file is built, not on import: other modules import the constants above.
function readInlineAssets(): InlineAssets {
  if (cachedAssets === undefined) {
    const css = readFileSync(fileURLToPath(new URL("./questionnaireStyles.css", import.meta.url)), "utf8");
    const script = readFileSync(fileURLToPath(new URL("./questionnaireClient.js", import.meta.url)), "utf8");
    if (/<\/style/i.test(css)) throw new Error("questionnaireStyles.css would close its own <style> tag.");
    if (/<\/script|<!--/i.test(script)) throw new Error("questionnaireClient.js would close its own <script> tag.");
    cachedAssets = { css, script };
  }
  return cachedAssets;
}

/**
 * One self-contained HTML file for a company: styles, script, catalog and brand are inline and
 * the page makes no request (RULE-ra-11). It carries the company name and id, the real
 * catalog and the brand of whoever delivers; nothing of any other company.
 */
export function buildQuestionnaireFile(input: QuestionnaireFileInput): QuestionnaireFile {
  const companyName = cleanText(input.company.name) ?? FALLBACK_COMPANY_NAME;
  const { css, script } = readInlineAssets();
  const html = [
    "<!doctype html>",
    '<html lang="pt-BR">',
    "<head>",
    '<meta charset="utf-8">',
    `<meta http-equiv="Content-Security-Policy" content="${CONTENT_SECURITY_POLICY}">`,
    '<meta name="viewport" content="width=device-width, initial-scale=1">',
    '<meta name="robots" content="noindex">',
    `<title>${escapeHtml(`Questionário de crescimento · ${companyName}`)}</title>`,
    `<style>\n${css}</style>`,
    "</head>",
    "<body>",
    '<main id="app"></main>',
    '<noscript><p class="fallback">Para responder, ative o JavaScript do navegador e abra este arquivo de novo.</p></noscript>',
    `<script type="application/json" id="fitpulse-data">${escapeJsonForHtml(buildEmbeddedData(input, companyName))}</script>`,
    `<script>\n${script}</script>`,
    "</body>",
    "</html>",
    "",
  ].join("\n");
  return { html, fileName: questionnaireFileName(companyName, input.sentAt), answersFileName: answersFileName(companyName) };
}

files.server/questionnaire/questionnaireStyles:
/*
 * Styles of the questionnaire file a client opens offline (RULE-ra-11).
 * Tokens follow "Tinta & Ouro" (src/styles/tokens.css): ink by default, porcelain when the
 * system asks for a light theme. Fonts are the system stacks of the identity: nothing is
 * embedded and nothing is fetched, so this sheet points at no other file.
 */
:root {
  --ground: #0b0a08;
  --ground-sunken: #0f0d0a;
  --surface: #161310;
  --surface-raised: #1d1914;
  --text: #f5f1e8;
  --text-soft: #cdc5b4;
  --text-muted: #958c7a;
  --line: rgba(224, 203, 163, 0.14);
  --line-strong: rgba(233, 214, 177, 0.28);
  --bronze: #a8c07a;
  --bronze-contrast: #0b0a08;
  --gold: #e8ba52;
  --gold-contrast: #0b0a08;
  --patina: #6ec6a2;
  --copper: #d8895b;
  --peril: #ee7c7c;
  --wash: rgba(168, 192, 122, 0.13);
  --ok-wash: rgba(110, 198, 162, 0.14);
  --warn-wash: rgba(216, 137, 91, 0.14);
  --font-structure: "Inter", "Segoe UI Variable Text", "Segoe UI", system-ui, -apple-system, "Helvetica Neue", sans-serif;
  --font-human: Georgia, "Iowan Old Style", "Palatino Linotype", "Book Antiqua", serif;
  --font-machine: "JetBrains Mono", "Cascadia Code", ui-monospace, Menlo, Consolas, monospace;
  color-scheme: dark;
}

@media (prefers-color-scheme: light) {
  :root {
    --ground: #f1ede3;
    --ground-sunken: #e9e4d6;
    --surface: #f9f6ee;
    --surface-raised: #fffdf7;
    --text: #1c1710;
    --text-soft: #4c4436;
    --text-muted: #6b6252;
    --line: rgba(92, 74, 44, 0.14);
    --line-strong: rgba(92, 74, 44, 0.26);
    --bronze: #55692a;
    --bronze-contrast: #fffdf7;
    --gold: #8a6512;
    --gold-contrast: #fffdf7;
    --patina: #177a58;
    --copper: #824421;
    --peril: #9e2d37;
    --wash: rgba(85, 105, 42, 0.13);
    --ok-wash: rgba(23, 122, 88, 0.14);
    --warn-wash: rgba(130, 68, 33, 0.14);
    color-scheme: light;
  }
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--ground);
  color: var(--text);
  font: 400 1rem/1.55 var(--font-structure);
  -webkit-text-size-adjust: 100%;
}

h1,
h2,
p {
  margin: 0;
}

button,
input,
select {
  font: inherit;
  color: inherit;
}

:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}

.shell {
  max-width: 760px;
  margin: 0 auto;
  padding: 24px 20px 72px;
}

.client-head {
  display: flex;
  align-items: center;
  gap: 14px;
  padding-bottom: 18px;
  border-bottom: 1px solid var(--line);
}

.brand-mark {
