  width: 48px;
  height: 48px;
  overflow: hidden;
  border: 1px solid var(--line-strong);
  border-radius: 10px;
  background: var(--surface);
  color: var(--bronze);
  font-weight: 700;
  font-size: 1.125rem;
}

.brand-mark img {
  display: block;
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
}

.brand-name {
  font-weight: 600;
}

.muted {
  color: var(--text-muted);
  font-size: 0.875rem;
}

.title {
  margin-top: 28px;
  font-size: 2rem;
  line-height: 1.15;
  letter-spacing: -0.03em;
}

.subtitle {
  margin-top: 6px;
  color: var(--text-soft);
}

.notice {
  display: flex;
  gap: 12px;
  align-items: flex-start;
  margin-top: 18px;
  padding: 12px 14px;
  border: 1px solid var(--line-strong);
  border-radius: 10px;
  background: var(--surface);
  color: var(--text-soft);
  font-size: 0.9375rem;
}

.notice-icon {
  flex: none;
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border: 1.5px solid currentColor;
  border-radius: 50%;
  font: 700 0.8125rem/1 var(--font-structure);
  color: var(--copper);
}

/* On a narrow screen or a touch device the notice stops being a side note. */
@media (max-width: 700px), (pointer: coarse) {
  .notice {
    border-color: var(--copper);
    background: var(--warn-wash);
    color: var(--text);
    font-weight: 600;
  }
}

.rail {
  display: flex;
  gap: 6px;
  margin-top: 22px;
}

.rail a {
  flex: 1;
  height: 12px;
  border-radius: 6px;
  background: var(--line-strong);
  position: relative;
}

.rail a::after {
  content: "";
  position: absolute;
  inset: -16px 0;
}

.rail a.done {
