import { useEffect, useRef, type ReactNode } from "react";
import { NavLink } from "react-router";
import type { Company } from "@/api/companiesApi";

interface CompanyTab {
  slug: string;
  path: string;
  label: string;
  meta?: ReactNode;
}

// Bronze line under the active tab; it draws itself only when the system allows motion (AC-ra-58)
function ActiveTabLine() {
  const lineRef = useRef<HTMLSpanElement>(null);
  useEffect(() => {
    const line = lineRef.current;
    if (!line || typeof line.animate !== "function") return;
    if (!window.matchMedia("(prefers-reduced-motion: no-preference)").matches) return;
    const animation = line.animate([{ transform: "scaleX(0)" }, { transform: "scaleX(1)" }], {
      duration: 360,
      easing: "cubic-bezier(.22,.61,.36,1)",
    });
    return () => animation.cancel();
  }, []);
  return <span ref={lineRef} aria-hidden="true" className="absolute inset-x-0 bottom-0 h-0.5 origin-left bg-bronze" />;
}

function buildTabs(company: Company): CompanyTab[] {
  return [
    {
      slug: "diagnosticos",
      path: "",
      label: "Diagnósticos",
      meta: <span className="font-mono text-xs font-medium text-text-muted max-sm:hidden">{company.completedCount}</span>,
    },
    { slug: "acoes", path: "acoes", label: "Ações" },
    { slug: "diario", path: "diario", label: "Diário" },
    { slug: "relatorios", path: "relatorios", label: "Relatórios" },
  ];
}

// Route tabs of the company; they sit right under the header so "Relatórios" stays in the first fold at 1280 and 390 px (AC-ra-61)
function CompanyTabs({ company }: { company: Company }) {
  const base = `/empresa/${encodeURIComponent(company.id)}`;
  return (
    <nav aria-label="Seções da empresa" data-aioson-tour="abas" className="mb-4 flex gap-0.5 overflow-x-auto border-b border-line [scrollbar-width:none]">
      {buildTabs(company).map((tab) => (
        <NavLink
          key={tab.slug}
          to={tab.path ? `${base}/${tab.path}` : base}
          end
          data-aioson-id={`tab-${tab.slug}`}
          className={({ isActive }) =>
            [
              "relative -mb-px inline-flex min-h-(--touch) items-center gap-2 whitespace-nowrap px-3.5 font-semibold no-underline max-sm:px-2 max-sm:text-sm",
              "motion-safe:transition-colors hover:text-text",
              isActive ? "text-text" : "text-text-soft",
            ].join(" ")
          }
        >
          {({ isActive }) => (
            <>
              {tab.label}
              {tab.meta}
              {isActive ? <ActiveTabLine /> : null}
            </>
          )}
        </NavLink>
      ))}
    </nav>
  );
}

export { CompanyTabs };

import { useId, useState, type ReactNode } from "react";
import { cn } from "@/lib/utils";
import type { Question } from "../../../shared/content/questionBank";
import type { AnswerValue } from "../../../shared/domain/types";

// Radio cards of the prototype: a label of at least 44px wraps each input (AC-dm-46)
const OPTION_CLASS = cn(
  "flex min-h-(--touch) cursor-pointer items-center gap-3 rounded-md border border-line-strong px-4 py-3",
  "transition-[border-color,background-color] duration-(--fast) ease-app hover:border-text-soft",
  "has-checked:border-bronze has-checked:bg-wash",
);
const RADIO_CLASS = "size-4 flex-none accent-bronze";
const UNKNOWN_VALUE = "unknown";

interface QuestionHeadingProps {
  title: ReactNode;
  help: ReactNode;
  helpLabel?: string;
  // Lets a fieldset name its group after the title
  titleId?: string;
}

// Question title with the "?" button that shows and hides its help (aria-expanded, AC-dm-11)
function QuestionHeading({ title, help, helpLabel = "O que significa esta pergunta?", titleId }: QuestionHeadingProps) {
  const [open, setOpen] = useState(false);
  const helpId = useId();
  return (
    <>
      <div className="flex items-start justify-between gap-2">
        <h2 id={titleId} className="text-lg leading-snug font-semibold">
          {title}
        </h2>
        <button
          type="button"
          className={cn(
            "grid size-8 flex-none cursor-pointer place-items-center rounded-full border border-line-strong font-serif text-base text-bronze italic",
            "relative before:absolute before:-inset-1.5 before:content-[''] hover:border-bronze",
          )}
          aria-expanded={open}
          aria-controls={helpId}
          aria-label={helpLabel}
          onClick={() => setOpen((value) => !value)}
        >
          ?
        </button>
      </div>
      <p
        id={helpId}
        hidden={!open}
        className="mt-2 rounded-md border border-line bg-surface px-4 py-3 text-sm text-text-soft"
      >
        {help}
      </p>
    </>
  );
}

interface AnchoredQuestionProps {
  question: Question;
  // undefined: not answered yet; null: "não sei"
  value: AnswerValue | undefined;
  onAnswer: (value: AnswerValue) => void;
  name: string;
}

// One question with its four anchors and, only where the catalog allows, "não sei" (AC-dm-11)
function AnchoredQuestion({ question, value, onAnswer, name }: AnchoredQuestionProps) {
  const titleId = useId();
  return (
    <fieldset
      className="m-0 min-w-0 border-0 border-b border-line px-0 py-6"
      aria-labelledby={titleId}
      data-aioson-id={`item-${question.id}`}
    >
      <QuestionHeading title={question.text} help={question.help} titleId={titleId} />
      <div className="mt-4 grid gap-2">
        {question.options.map((option) => (
          <label key={option.value} className={OPTION_CLASS}>
            <input
              type="radio"
              className={RADIO_CLASS}
              name={name}
              value={option.value}
              checked={value === option.value}
              onChange={() => onAnswer(option.value)}
            />
            <span>{option.label}</span>
          </label>
        ))}
        {question.unknownLabel !== null ? (
          <label className={cn(OPTION_CLASS, "border-dashed")}>
            <input
              type="radio"
              className={RADIO_CLASS}
              name={name}
              value={UNKNOWN_VALUE}
              checked={value === null}
              onChange={() => onAnswer(null)}
            />
            <span>{question.unknownLabel}</span>
          </label>
        ) : null}
      </div>
    </fieldset>
  );
}

export { AnchoredQuestion, OPTION_CLASS, QuestionHeading, RADIO_CLASS };

