import type { ReactNode } from "react";
import { rulesV1 } from "../../../shared/rules/rulesV1";
import { computeUnitEconomics } from "../../../shared/domain/unitEconomics";
import type { CalculatorInput, UnitEconomics } from "../../../shared/domain/types";
import { formatMoney } from "../../../shared/format/money";
import {
  NO_NEW_CUSTOMERS_EXPLANATION,
  NOT_CALCULATED_LABEL,
  formatPayback,
  formatRatioWithBand,
  getRatioBand,
} from "../../../shared/format/displayNumbers";

const ESTIMATED_NOTE = "estimado por faixa";
const PAYBACK_LIMIT_MONTHS = 12;

function moneyOrNotCalculated(cents: number | null): string {
  return cents === null ? NOT_CALCULATED_LABEL : formatMoney(cents);
}

function withEstimate(text: string, economics: UnitEconomics): string {
  return economics.origin === "estimated" ? `${text} (${ESTIMATED_NOTE})` : text;
}

function hasNoNewCustomers(economics: UnitEconomics): boolean {
  return economics.newCustomersOrigin === "measured" && economics.newCustomers === 0;
}

function costNote(economics: UnitEconomics): string {
  if (economics.cacCents !== null) return withEstimate("Gasto ÷ clientes novos", economics);
  return hasNoNewCustomers(economics) ? NO_NEW_CUSTOMERS_EXPLANATION : "";
}

function ratioNote(economics: UnitEconomics): string {
  const band = getRatioBand(economics.ratio);
  return band === null ? "" : withEstimate(band.phrase, economics);
}

function paybackNote(economics: UnitEconomics): string {
  if (economics.neverPaysBack) return "Sem lucro por mês, o custo do cliente não volta.";
  if (economics.paybackMonths === null) return "";
  const note = economics.paybackMonths <= PAYBACK_LIMIT_MONTHS ? "Dentro de 12 meses." : "Mais de 12 meses: o caixa fica preso.";
  return withEstimate(note, economics);
}

function Figure({ label, value, note }: { label: string; value: string; note: ReactNode }) {
  return (
    <>
      <dt className="mt-4 text-sm text-text-muted">{label}</dt>
      <dd className="m-0 font-mono text-2xl leading-snug font-medium">
        {value}
        {note ? <small className="mt-0.5 block font-sans text-xs text-text-soft">{note}</small> : null}
      </dd>
    </>
  );
}

// Recalculates cost per customer, profit per customer, their ratio and the payback on every change
// (AC-dm-15, AC-dm-51); nothing here ever shows NaN, Infinity or an empty value.
function UnitEconomicsPanel({ calculator }: { calculator: CalculatorInput }) {
  const economics = computeUnitEconomics(calculator, rulesV1);
  const costUnknown = economics.cacCents === null && !hasNoNewCustomers(economics);
  return (
    <aside
      aria-live="polite"
      data-aioson-id="calc-output"
      className="rounded-lg border border-line-strong bg-surface p-6 lg:sticky lg:top-26"
    >
      <h3 className="mb-2">Seus números, calculados</h3>
      {costUnknown ? (
        <p className="text-sm text-text-muted">
          Sem o gasto ou o número de clientes novos, o app não calcula o custo de um cliente. Tudo bem: isso vira a
          primeira ação do seu plano.
        </p>
      ) : null}
      <dl className="m-0">
        <Figure
          label="Custo para conquistar um cliente"
          value={moneyOrNotCalculated(economics.cacCents)}
          note={costNote(economics)}
        />
        <Figure
          label="Quanto um cliente deixa de lucro"
          value={moneyOrNotCalculated(economics.ltvCents)}
          note={economics.ltvCents === null ? "Preencha a compra típica" : "Valor × compras por ano × tempo × margem"}
        />
        <Figure label="Relação entre os dois" value={formatRatioWithBand(economics.ratio)} note={ratioNote(economics)} />
        <Figure
          label="Tempo para o cliente se pagar"
          value={formatPayback(economics.neverPaysBack ? "never" : economics.paybackMonths)}
          note={paybackNote(economics)}
        />
      </dl>
    </aside>
  );
}

export { UnitEconomicsPanel };

import { useCallback, useEffect, useRef, useState } from "react";
import { isApiError } from "@/api/httpClient";
import { updateDiagnosis, type Diagnosis, type DiagnosisPatch } from "@/api/diagnosesApi";
import type {
  Answers,
  AnswerValue,
  BlockNumber,
  CalculatorInput,
  QuestionId,
} from "../../../shared/domain/types";

type SaveState = "saved" | "saving" | "error";

interface CalculatorChangeOptions {
  // Typed values wait a short pause before saving; choices save at once
  typed?: boolean;
}

interface DraftAutosave {
  answers: Answers;
  calculator: CalculatorInput;
  currentBlock: BlockNumber;
  saveState: SaveState;
  savedAt: Date | null;
  saveError: string | null;
  setAnswer: (id: QuestionId, value: AnswerValue) => void;
  setCalculator: (next: CalculatorInput, options?: CalculatorChangeOptions) => void;
  setCurrentBlock: (block: BlockNumber) => void;
  retry: () => void;
  // Sends what is still pending and rejects when the save fails
  flush: () => Promise<void>;
  // Drops pending changes and stops saving (the draft is being discarded)
  cancel: () => void;
}

const TYPING_PAUSE_MS = 600;

function toDate(iso: string): Date | null {
  const date = new Date(iso);
  return Number.isNaN(date.getTime()) ? null : date;
}

function describeSaveError(error: unknown): string {
  if (isApiError(error) && error.code === "diagnosis_not_draft") {
    return "Este diagnóstico já foi concluído. As últimas mudanças não foram salvas.";
  }
  return "Não foi possível salvar. Suas respostas continuam nesta tela.";
}

function hasKeys(patch: DiagnosisPatch): boolean {
  return Object.keys(patch).length > 0;
}

interface SaveQueue {
  saveState: SaveState;
  savedAt: Date | null;
  saveError: string | null;
  saveSoon: (patch: DiagnosisPatch, typed?: boolean) => void;
  flush: () => Promise<void>;
  cancel: () => void;
}

// Sends PATCH requests one at a time; changes made while one runs go in the next one.
function useSaveQueue(diagnosisId: string, lastSavedIso: string): SaveQueue {
  const [saveState, setSaveState] = useState<SaveState>("saved");
  const [savedAt, setSavedAt] = useState<Date | null>(() => toDate(lastSavedIso));
  const [saveError, setSaveError] = useState<string | null>(null);
  const pendingRef = useRef<DiagnosisPatch>({});
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const inFlightRef = useRef<Promise<void> | null>(null);
  const cancelledRef = useRef(false);

  const clearTimer = useCallback(() => {
    if (timerRef.current !== null) clearTimeout(timerRef.current);
    timerRef.current = null;
  }, []);

  const drain = useCallback(async () => {
    while (!cancelledRef.current && hasKeys(pendingRef.current)) {
      const patch = pendingRef.current;
      pendingRef.current = {};
      setSaveState("saving");
      try {
        await updateDiagnosis(diagnosisId, patch);
        setSavedAt(new Date());
        setSaveError(null);
      } catch (error) {
        pendingRef.current = { ...patch, ...pendingRef.current };
        setSaveState("error");
        setSaveError(describeSaveError(error));
        throw error;
      }
    }
    setSaveState("saved");
  }, [diagnosisId]);

  const flush = useCallback((): Promise<void> => {
    clearTimer();
    if (inFlightRef.current) return inFlightRef.current;
    const run = drain().finally(() => {
      inFlightRef.current = null;
    });
    inFlightRef.current = run;
    return run;
  }, [clearTimer, drain]);

  const saveSoon = useCallback(
    (patch: DiagnosisPatch, typed = false) => {
      if (cancelledRef.current) return;
      pendingRef.current = { ...pendingRef.current, ...patch };
      clearTimer();
      if (typed) timerRef.current = setTimeout(() => void flush().catch(() => undefined), TYPING_PAUSE_MS);
      else void flush().catch(() => undefined);
    },
    [clearTimer, flush],
  );

  const cancel = useCallback(() => {
    cancelledRef.current = true;
    clearTimer();
    pendingRef.current = {};
  }, [clearTimer]);

  // Leaving the screen or closing the window sends a typed value still waiting for its pause
  useEffect(() => {
    const sendPending = () => {
      if (hasKeys(pendingRef.current)) void flush().catch(() => undefined);
    };
    window.addEventListener("pagehide", sendPending);
    return () => {
      window.removeEventListener("pagehide", sendPending);
      sendPending();
    };
  }, [flush]);

  return { saveState, savedAt, saveError, saveSoon, flush, cancel };
}

// Keeps the draft on screen and saves each change through PATCH /api/diagnoses/:id (AC-dm-12).
function useDraftAutosave(diagnosis: Diagnosis): DraftAutosave {
  const [answers, setAnswersState] = useState<Answers>(() => diagnosis.answers ?? {});
  const [calculator, setCalculatorState] = useState<CalculatorInput>(() => diagnosis.calculator);
  const [currentBlock, setCurrentBlockState] = useState<BlockNumber>(() => diagnosis.currentBlock);
  const answersRef = useRef(answers);
  const { saveSoon, flush, ...queue } = useSaveQueue(diagnosis.id, diagnosis.updatedAt);

  const setAnswer = useCallback(
    (id: QuestionId, value: AnswerValue) => {
      const next = { ...answersRef.current, [id]: value };
      answersRef.current = next;
      setAnswersState(next);
      saveSoon({ answers: next });
    },
    [saveSoon],
  );

  const setCalculator = useCallback(
    (next: CalculatorInput, options: CalculatorChangeOptions = {}) => {
      setCalculatorState(next);
      saveSoon({ calculator: next }, options.typed);
    },
    [saveSoon],
  );

  const setCurrentBlock = useCallback(
    (block: BlockNumber) => {
      setCurrentBlockState(block);
      saveSoon({ currentBlock: block });
    },
    [saveSoon],
  );

  const retry = useCallback(() => void flush().catch(() => undefined), [flush]);

  return { ...queue, answers, calculator, currentBlock, setAnswer, setCalculator, setCurrentBlock, retry, flush };
}

export { useDraftAutosave };
export type { CalculatorChangeOptions, DraftAutosave, SaveState };

