/* Only the app's own sources are scanned. Automatic detection would also read the AIOSON folders,
   logs and test output (the folder is not a git repository, so .gitignore does not apply): every
   write there made the dev server reload the page, and their words became classes in the bundle. */
@import "tailwindcss" source(none);
@source "../";
@import "./tokens.css";

/* Bind Tailwind to the app tokens. The default palette and shadows are dropped:
   no structural blue can leak in, and depth comes only from borders. */
@theme inline {
  --color-*: initial;
  --shadow-*: initial;
  --inset-shadow-*: initial;
  --drop-shadow-*: initial;

  --color-ground: var(--ground);
  --color-ground-sunken: var(--ground-sunken);
  --color-surface: var(--surface);
  --color-surface-raised: var(--surface-raised);
  --color-solid: var(--solid);
  --color-text: var(--text);
  --color-text-soft: var(--text-soft);
  --color-text-muted: var(--text-muted);
  --color-line: var(--line);
  --color-line-strong: var(--line-strong);
  --color-bronze: var(--bronze);
  --color-bronze-contrast: var(--bronze-contrast);
  --color-gold: var(--gold);
  --color-gold-contrast: var(--gold-contrast);
  --color-accent: var(--accent);
  --color-accent-contrast: var(--accent-contrast);
  --color-wash: var(--wash);
  --color-ok: var(--ok);
  --color-ok-wash: var(--ok-wash);
  --color-warn: var(--warn);
  --color-warn-wash: var(--warn-wash);
  --color-danger: var(--danger);
  --color-danger-wash: var(--danger-wash);
  --color-danger-contrast: var(--peril-contrast);
  --color-scrim: var(--scrim);

  --font-sans: var(--font-structure);
  --font-serif: var(--font-human);
  --font-mono: var(--font-machine);

  --radius-sm: var(--r-sm);
  --radius-md: var(--r-md);
  --radius-lg: var(--r-lg);

  --ease-app: var(--ease);
}

@layer base {
  html {
    background: var(--ground);
    color: var(--text);
    font-family: var(--font-structure);
    font-size: 16px;
    line-height: 1.6;
    -webkit-text-size-adjust: 100%;
    scrollbar-color: var(--line-strong) var(--ground);
  }

  body {
    margin: 0;
    min-height: 100vh;
    background: var(--ground);
    font-variant-numeric: tabular-nums;
    position: relative;
    isolation: isolate;
  }

  /* D-04 dust: nebula in the app metal plus gold/bronze sparks, a single fixed layer */
  body::before {
    content: "";
    position: fixed;
    inset: 0;
    z-index: -1;
    pointer-events: none;
    background:
      radial-gradient(2px 2px at 78% 14%, var(--gold) 50%, transparent 51%),
      radial-gradient(1.5px 1.5px at 66% 22%, var(--bronze) 50%, transparent 51%),
      radial-gradient(1.5px 1.5px at 88% 30%, var(--gold) 50%, transparent 51%),
      radial-gradient(2px 2px at 58% 9%, var(--bronze) 50%, transparent 51%),
      radial-gradient(1.5px 1.5px at 93% 8%, var(--bronze) 50%, transparent 51%),
      radial-gradient(1.5px 1.5px at 71% 36%, var(--gold) 50%, transparent 51%),
      radial-gradient(900px 460px at 80% -8%, color-mix(in oklab, var(--bronze) 15%, transparent), transparent 72%),
      radial-gradient(700px 380px at 6% 110%, color-mix(in oklab, var(--gold) 6%, transparent), transparent 70%);
    animation: breathe 8s ease-in-out infinite;
  }

  :root[data-theme="light"] body::before {
    animation: none;
    opacity: 0.55;
  }

  ::selection {
    background: var(--bronze);
    color: var(--bronze-contrast);
  }

  input,
  select,
  textarea,
  button {
    font: inherit;
    color: inherit;
    caret-color: var(--bronze);
  }

  /* Keyboard focus is always visible, in gold */
  :focus-visible {
    outline: 2px solid var(--focus-ring);
    outline-offset: 2px;
    border-radius: var(--r-sm);
  }

  a {
    color: var(--bronze);
    text-decoration-thickness: 1px;
    text-underline-offset: 3px;
  }

  a:hover {
    text-decoration-thickness: 2px;
  }

  h1,
  h2,
  h3 {
    font-family: var(--font-structure);
    font-weight: 700;
    line-height: 1.15;
    margin: 0;
    color: var(--text);
    letter-spacing: -0.02em;
    text-wrap: balance;
  }

  h1 {
    font-size: var(--t-36);
    letter-spacing: -0.03em;
  }

  h2 {
    font-size: var(--t-24);
  }

  h3 {
    font-size: var(--t-18);
    font-weight: 600;
    letter-spacing: -0.01em;
  }

  p {
    margin: 0;
    text-wrap: pretty;
  }
}

/* Human voice: the serif italic that speaks to the owner */
@utility voice-human {
  font-family: var(--font-human);
  font-style: italic;
  font-weight: 400;
  letter-spacing: 0;
  color: var(--bronze);
}

/* Machine voice: mono uppercase meta line (D-01) */
@utility meta-line {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-machine);
  font-size: var(--t-12);
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--text-muted);
}

@keyframes breathe {
  0%,
  100% {
    opacity: 0.62;
    filter: brightness(0.82);
  }
  50% {
    opacity: 1;
    filter: brightness(1.18);
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation: none !important;
    transition: none !important;
    scroll-behavior: auto !important;
  }
}

/* Report center (CAP-ra-report-center): options on the left, the paged preview on the right.
   The sheets paint with the paper palette of the PDF (`--p-*`, set by ReportSheet from
   shared/report/paperPalette.ts), never with the app theme. */
@layer components {
  .report-center {
    display: grid;
    grid-template-columns: minmax(0, 0.9fr) minmax(0, 1.1fr);
    gap: 40px;
    align-items: start;
  }
  .report-options {
    display: flex;
    flex-direction: column;
    gap: 20px;
  }
  .report-types {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
  }
  .report-type {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    min-height: var(--touch);
    padding: 0 14px;
    border: 1px solid var(--line-strong);
    border-radius: var(--r-md);
    background: none;
    color: var(--text-soft);
    font: 600 0.9375rem var(--font-structure);
    cursor: pointer;
  }
  .report-type[aria-checked="true"] {
    border-color: var(--bronze);
    background: var(--wash);
    color: var(--text);
  }
  .report-type[aria-disabled="true"] {
    opacity: 0.55;
    cursor: not-allowed;
  }
  .report-switch {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    min-height: var(--touch);
    padding: 4px 0;
    cursor: pointer;
  }
  .report-switch input {
    appearance: none;
    position: relative;
    flex: none;
    width: 40px;
    height: 24px;
    margin: 0;
    border: 1px solid var(--line-strong);
    border-radius: 12px;
    background: var(--surface-raised);
    cursor: pointer;
  }
  .report-switch input::after {
    content: "";
    position: absolute;
    top: 3px;
    left: 3px;
    width: 16px;
    height: 16px;
    border-radius: 50%;
    background: var(--text-muted);
  }
  .report-switch input:checked {
    border-color: var(--bronze);
    background: var(--wash);
  }
  .report-switch input:checked::after {
    transform: translateX(16px);
    background: var(--bronze);
  }
  .report-switch b {
    display: block;
    font-size: 0.9375rem;
    font-weight: 600;
  }
  .report-switch small {
    display: block;
    font-size: 0.8125rem;
    color: var(--text-muted);
  }

  .report-preview {
    position: sticky;
    top: 16px;
    min-width: 0;
  }
  .report-preview-head {
    display: flex;
    flex-wrap: wrap;
    align-items: flex-start;
    justify-content: space-between;
    gap: 12px;
    margin-bottom: 12px;
  }
  .report-preview-label {
    padding-top: 10px;
    font: 500 0.8125rem var(--font-machine);
    color: var(--text-muted);
  }
  .report-pages {
    position: relative;
    display: flex;
    flex-direction: column;
    gap: 18px;
    max-height: calc(100vh - 160px);
    overflow: auto;
    padding: 18px;
    border: 1px solid var(--line);
    border-radius: var(--r-lg);
    background: var(--ground-sunken);
    scroll-snap-type: y proximity;
    scrollbar-color: color-mix(in oklab, var(--text-muted) 55%, transparent) transparent;
  }
  .report-sheet-skeleton {
    flex: none;
    aspect-ratio: 210 / 297;
    border-radius: 4px;
    background: color-mix(in oklab, var(--surface-raised) 80%, transparent);
  }

  .report-delivery {
    display: flex;
    flex: 1 1 260px;
    flex-direction: column;
    align-items: flex-end;
    gap: 8px;
  }
  .report-delivery-panel {
    width: 100%;
    max-width: 44ch;
    padding: 12px 16px;
    border: 1px solid var(--line);
    border-radius: var(--r-md);
    background: var(--surface);
    font-size: 0.875rem;
    text-align: left;
  }
  .report-delivery-panel.is-error {
    border-color: var(--danger);
    background: var(--danger-wash);
  }

  /* One A4 page: the 210 x 297 shape, growing only if a block ever needs more room */
  .report-sheet {
    position: relative;
    flex: none;
    display: flex;
    flex-direction: column;
    width: 100%;
    aspect-ratio: 210 / 297;
    container-type: inline-size;
    contain: paint;
    border-radius: 3px;
    background: var(--p-paper);
    color: var(--p-ink);
    font-weight: 400;
    letter-spacing: 0;
    scroll-snap-align: start;
