    flex-direction: column;
    gap: 1.8cqw;
    margin: 0;
  }
  .sheet-explained dt {
    font-weight: 600;
  }
  .sheet-explained dd {
    display: flex;
    flex-direction: column;
    margin: 0;
  }
  .sheet-explained b {
    font-size: 3cqw;
    font-weight: 500;
  }
  .sheet-list {
    display: flex;
    flex-direction: column;
    gap: 1cqw;
    margin: 0;
    padding-left: 3cqw;
  }
  .sheet-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 1.9cqw;
  }
  .sheet-table th {
    padding: 1cqw 0.6cqw;
    border-bottom: 1px solid var(--p-ink);
    font-weight: 600;
    text-align: left;
    color: var(--p-soft);
  }
  .sheet-table td {
    padding: 1cqw 0.6cqw;
    border-bottom: 1px solid var(--p-line);
    vertical-align: top;
  }
  .sheet-notice {
    padding: 2cqw 2.4cqw;
    border: 1px solid var(--p-line);
    border-radius: 1cqw;
    background: var(--p-panel);
    color: var(--p-soft);
  }

  /* 390 px and other narrow screens: the options above, the sheets stacked in the page flow */
  @media (max-width: 860px) {
    .report-center {
      grid-template-columns: minmax(0, 1fr);
      gap: 28px;
    }
    .report-preview {
      position: static;
    }
    .report-pages {
      max-height: none;
      overflow: visible;
      padding: 12px;
    }
    .report-delivery {
      align-items: stretch;
    }
    .report-delivery-panel {
      max-width: none;
    }
  }
}

/* The reprint band (700 ms) and the page entry (220 ms) only run when the owner did not ask for
   less motion; with prefers-reduced-motion: reduce the sheets appear in their final state (AC-ra-58) */
@keyframes report-reprint {
  0% {
    transform: translateY(-100%);
    opacity: 0;
  }
  15% {
    opacity: 1;
  }
  100% {
    transform: translateY(250%);
    opacity: 0;
  }
}

@keyframes report-page-in {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes report-skeleton-pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.55;
  }
}

@media (prefers-reduced-motion: no-preference) {
  .report-sheet {
    animation: report-page-in var(--dur) var(--ease);
  }
  .report-sheet.is-reprinted::after {
    animation: report-reprint 700ms var(--ease) 1;
  }
  .report-sheet-skeleton {
    animation: report-skeleton-pulse 1.4s var(--ease) infinite;
  }
  .report-switch input,
  .report-switch input::after {
    transition:
      background var(--fast) var(--ease),
      border-color var(--fast) var(--ease),
      transform var(--fast) var(--ease);
  }
}

