const LOOPBACK_HOSTS = new Set(["127.0.0.1", "localhost", "[::1]"]);

function isLocal(url: URL): boolean {
  return LOOPBACK_HOSTS.has(url.hostname) || url.protocol === "data:" || url.protocol === "blob:";
}

